def await_id(n):
 global buf
 deadline=time.monotonic()+15
 while time.monotonic()<deadline:
  if n in msgs:return msgs[n]
  if not sel.select(1):continue
  chunk=os.read(p.stdout.fileno(),65536)
  if not chunk:break
  buf+=chunk
  while b'\n' in buf:
   line,buf=buf.split(b'\n',1)
   try:x=json.loads(line)
   except ValueError:continue
   if isinstance(x,dict) and type(x.get('id')) is int:msgs[x['id']]=x
 raise TimeoutError('MCP_STATUS_RESPONSE_MISSING_'+str(n))
try:
 send({'jsonrpc':'2.0','id':1,'method':'initialize','params':{'protocolVersion':'2025-06-18','capabilities':{},'clientInfo':{'name':'gace-mcp-run-status','version':'1'}}})
 if 'protocolVersion' not in await_id(1).get('result',{}):sys.exit(71)
 send({'jsonrpc':'2.0','method':'notifications/initialized','params':{}})
 send({'jsonrpc':'2.0','id':2,'method':'tools/call','params':{'name':'debugai_status','arguments':{'run_id':rid}}})
 r=await_id(2).get('result',{})
 data={}
 for b in r.get('content',[]):
  if b.get('type')=='text':
   try:data=json.loads(b.get('text',''))
   except ValueError:pass
   break
 print('MCP_STATUS_RESPONSE=RECEIVED')
 print('MCP_STATUS_SCHEMA='+str(data.get('schema','UNKNOWN'))[:50])
 print('MCP_STATUS_TOOL='+str(data.get('tool','UNKNOWN'))[:50])
 print('MCP_STATUS_EXIT='+str(data.get('exit_code','UNKNOWN'))[:10])
 if r.get('isError') is True or data.get('schema')!='debugai.mcp-result/v1' or data.get('tool')!='debugai_status' or data.get('exit_code')!=0:
  sys.exit(72)
 print('MCP_REAL_RUN_STATUS=PASS')
except TimeoutError as e:
 print(str(e));sys.exit(73)
finally:
 p.stdin.close()
 if p.poll() is None:p.terminate()
 try:p.wait(timeout=4)
 except subprocess.TimeoutExpired:p.kill()
